-- Physics GCE A/L 2017 curriculum hierarchy based on the official NIE syllabus.
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),s as(select id from public.subjects where name='Physics'),x(code,title,position) as(values ('1.0','Measurement',1),('2.0','Mechanics',2),('3.0','Oscillations and Waves',3),('4.0','Thermal Physics',4),('5.0','Gravitational Field',5),('6.0','Electrostatic Field',6),('7.0','Magnetic Field',7),('8.0','Current Electricity',8),('9.0','Electronics',9),('10.0','Mechanical Properties of Matter',10),('11.0','Matter and Radiation',11))
insert into public.syllabus_competencies(syllabus_version_id,subject_id,code,title,description,position)
select v.id,s.id,x.code,x.title,'NIE GCE A/L Physics 2017 Unit '||x.position||' competency.',x.position from v cross join s cross join x
where not exists(select 1 from public.syllabus_competencies z where z.syllabus_version_id=v.id and z.subject_id=s.id and z.code=x.code);
