e',4),('6.5.1','6.0','Dielectrics',5),('6.6.1','6.0','Energy stored in capacitors',6),('7.1.1','7.0','Magnetic fields',1),('7.2.1','7.0','Force on a moving charge',2),('7.3.1','7.0','Force on a current carrying conductor',3),('7.4.1','7.0','Motion of charged particles in magnetic fields',4),('7.5.1','7.0','Electromagnetic induction',5),('7.6.1','7.0','Faraday and Lenz laws',6),('8.1.1','8.0','Electric current and potential difference',1),('8.2.1','8.0','Resistance and resistivity',2),('8.3.1','8.0','Circuit laws',3),('8.4.1','8.0','Kirchhoff laws',4),('8.5.1','8.0','Electrical energy and power',5),('8.6.1','8.0','Cells and internal resistance',6),('8.7.1','8.0','Measuring instruments',7),('9.1.1','9.0','Semiconductors',1),('9.2.1','9.0','p-n junction',2),('9.3.1','9.0','Diodes and rectification',3),('9.4.1','9.0','Transistors',4),('9.5.1','9.0','Transistor amplification',5),('9.6.1','9.0','Digital electronics',6),('9.7.1','9.0','Logic gates and applications',7),('10.1.1','10.0','Elasticity',1),('10.2.1','10.0','Stress and strain',2),('10.3.1','10.0','Young modulus',3),('10.4.1','10.0','Viscosity',4),('10.5.1','10.0','Fluid flow',5),('10.6.1','10.0','Surface tension',6),('10.7.1','10.0','Stokes law and terminal velocity',7),('11.1.1','11.0','Black body radiation',1),('11.2.1','11.0','Photoelectric effect',2),('11.3.1','11.0','Wave-particle duality',3),('11.4.1','11.0','X-rays',4),('11.5.1','11.0','Radioactivity',5),('11.6.1','11.0','Nuclear structure',6),('11.7.1','11.0','Mass defect and binding energy',7),('11.8.1','11.0','Nuclear fission and fusion',8),('11.9.1','11.0','Nuclear energy and radiation safety',9))
insert into public.syllabus_competency_levels(competency_id,syllabus_version_id,subject_id,code,title,description,position)
select c.id,v.id,s.id,x.code,x.title,'Curriculum learning area from the official NIE Physics 2017 syllabus.',x.position
from v cross join s cross join x join public.syllabus_competencies c on c.syllabus_version_id=v.id and c.subject_id=s.id and c.code=x.cc
where not exists(select 1 from public.syllabus_competency_levels z where z.syllabus_version_id=v.id and z.subject_id=s.id and z.code=x.code);
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),s as(select id from public.subjects where name='Physics'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from s))
insert into public.syllabus_subtopics(topic_id,title,description,position)
select t.id,'Core learning outcomes','NIE GCE A/L Physics 2017 curriculum learning area.',1
from cl join public.syllabus_topics t on t.title=cl.title join public.syllabus_units u on u.id=t.unit_id and u.position=split_part(cl.code,'.',1)::int and u.subject_id=cl.subject_id and u.syllabus_version_id=cl.syllabus_version_id
where not exists(select 1 from public.syllabus_subtopics z where z.topic_id=t.id and z.title='Core learning outcomes');
with v as(select id from public.syllabus_versions where code='GCE_AL_2017'),s as(select id from public.subjects where name='Physics'),cl as(select * from public.syllabus_competency_levels where syllabus_version_id=(select id from v) and subject_id=(select id from s))
insert into public.syllabus_learning_outcomes(subtopic_id,competency_id,competency_level_id,code,statement,position)
select st.id,cl.competency_id,cl.id,cl.code,cl.title,1
from cl join public.syllabus_topics t on t.title=cl.title join public.syllabus_units u on u.id=t.unit_id and u.position=split_part(cl.code,'.',1)::int and u.subject_id=cl.subject_id and u.syllabus_version_id=cl.syllabus_version_id
join public.syllabus_subtopics st on st.topic_id=t.id and st.title='Core learning outcomes'
where not exists(select 1 from public.syllabus_learning_outcomes z where z.subtopic_id=st.id and z.code=cl.code);
